def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    emit(g, "Start: background, 8-walls, and small coloured pieces; pieces sharing a colour will be linked.")

    def seg(p, q):
        out = []; y, x = p
        dy = int(np.sign(q[0] - y)); dx = int(np.sign(q[1] - x))
        while (y, x) != q:
            y += dy; x += dx; out.append((y, x))
        return out

    def lpath(a, b, vfirst):
        c = (b[0], a[1]) if vfirst else (a[0], b[1])
        pts = seg(a, c) + seg(c, b)
        return pts[:-1]

    colours = sorted(set(int(v) for v in np.unique(g)) - {bg, 8})
    for col in colours:
        while True:
            comps = components(g == col)
            if len(comps) < 2:
                break
            gid = {}
            for i, cs in enumerate(comps):
                for c in cs:
                    gid[c] = i

            def axis(c):
                i = gid[c]; y, x = c
                if any(gid.get((y + d, x)) == i for d in (-1, 1)): return 'v'
                if any(gid.get((y, x + d)) == i for d in (-1, 1)): return 'h'
                return None

            best = None
            for i in range(len(comps)):
                for j in range(i + 1, len(comps)):
                    for a in comps[i]:
                        for b in comps[j]:
                            d = abs(a[0] - b[0]) + abs(a[1] - b[1])
                            opts = []
                            for vf in (True, False):
                                p = lpath(a, b, vf)
                                if all(g[c] == bg for c in p):
                                    opts.append((vf, p))
                            if not opts:
                                continue
                            straight = a[0] == b[0] or a[1] == b[1]
                            if straight or len(opts) == 1:
                                det, p = True, opts[0][1]
                            else:
                                ax = axis(a); bx = axis(b)
                                if ax:
                                    det, p = True, lpath(a, b, ax == 'v')
                                elif bx:
                                    det, p = True, lpath(b, a, bx == 'v')
                                else:
                                    det, p = False, opts[0][1]
                            key = (not det, d)
                            if best is None or key < best[0]:
                                best = (key, p, a, b)
            if best is None:
                break
            for c in best[1]:
                g[c] = col
            emit(g, f"Link colour {col}: connect the nearest pieces {best[2]} and {best[3]} with a path through background.")
    emit(g, "All same-coloured pieces are joined; final grid.")
    return g
